Write-Host "Instalando dependencias do Host (VirtualBox e Vagrant)..." -ForegroundColor Cyan; winget install Oracle.VirtualBox --silent --accept-package-agreements --accept-source-agreements; winget install Hashicorp.Vagrant --silent --accept-package-agreements --accept-source-agreements; Write-Host ">>> Instalacao concluida! Por favor, reinicie o seu terminal (feche e abra o VS Code) para que o comando vagrant seja reconhecido. <<<" -ForegroundColor Green
